package com.demo.basics;

public class SimpleInterest {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int SI;
		int p=1000;
		int r=2;
		int t = 45;
		SI=(p*r*t)/100;
		int amount=SI+p;
		System.out.println("simple Interset:"+SI+" \n"+"amount is:"+amount);
	}

}
